quests[8947] = { id = 8947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions merkwürdige Anforderung", description = "Wir waren uns der Wichtigkeit von Valthalaks Amulett nicht bewusst, also wurde es zusammen mit der restlichen Beute aufgeteilt. Das erste Stück bekam ein Zwerg namens Theldren. Ich habe versucht, es mir von ihm zurückzuholen und er hätte mich fast zu Tode geprügelt. Ihr werdet ihm sein Stück gewaltsam entreißen müssen.\n\nDas Letzte, was ich über ihn hörte, ist, dass er ein Gladiator für die Dunkeleisenzwerge geworden ist. Ihn zum offenen Kampf zu bewegen, dürfte sich jedoch schwierig gestalten.\n\nBringt mir die folgenden Materialien, Ihr werdet sie brauchen.", sourceObjective = "Bringt Anthion Harmon in den östlichen Pestländern 3 Dunkeleisenbarren, 20 verzaubertes Leder, 3 Mondstoff und 4 geschmeidige unverwüstliche Bälge", progress = "Habt Ihr die Materialien, um die ich Euch gebeten habe, {name}?", completion = "Exzellent. Ich werde diese Dinge in etwas umwandeln, dass für uns von größerem Nutzen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[8948] = { id = 8948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions alter Freund", description = "Theldren würde sich niemals freiwillig einem fairen Kampf stellen. Deshalb habe ich dieses Banner mit seinem Familienwappen hergestellt.\n\nMit der richtigen Verzauberung belegt, sollte es für ihn eine Provokation darstellen, die er nicht ignorieren kann.\n\nEin alter Kollege von mir namens Falrin weiß, was zu tun ist. Er versteht sich darauf... Leute zu verärgern. Ihr findet ihn in der Bibliothek von Düsterbruch.", sourceObjective = "Bringt Falrin Rankenweber in der Bibliothek von Düsterbruch das unvervollständigte Banner der Provokation.", progress = "Sprecht, Fremder, seht Ihr nicht, dass ich beschäftigt bin?", completion = "Anthion schickt Euch, sagt Ihr? Ich dachte, er wäre tot. Allerdings habe ich in meinem Leben schon weit seltsamere Dinge gehört.\n\nNun denn, was soll ich für Euch mit diesem Banner anstellen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8949] = { id = 8949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falrins Rachefeldzug", description = "Ja, ich bin fürwahr mit der Verzauberung vertraut, die Ihr benötigt, {class}. Aber alles hat seinen Preis, selbst wenn Euch ein alter Freund schickt.\n\nIch hasse und verabscheue meine barbarischen Ogernachbarn von ganzem Herzen. Und nicht nur die, ich hasse die Anhänger von Omokk genauso sehr, wie ich die Anhänger von König Gordok verabscheue.\n\nIch will, dass Ihr sie tötet, und zwar Unmengen von ihnen! Bringt mir die Perlen, die sie um den Hals tragen, als Beweis für Eure Taten. Solltet Ihr dies für mich tun, können wir uns weiter über den Gefallen unterhalten, den Ihr von mir verlangt.", sourceObjective = "Nehmt den Ogern in der Schwarzfelsspitze oder in Düsterbruch 25 Ogerkriegsperlen ab und bringt sie zu Falrin Rankenweber im Athenaeum, der Bibliothek von Düsterbruch.", progress = "Habt Ihr die Gefallen erledigt, um den ich Euch gebeten habe, {name}?", completion = "Hmmm... Verwunderlicherweise fühle ich mich keinen Deut besser, jetzt da mein Bruder durch die Hände dieser Rohlinge gefallen ist.\n\nNun, Ihr habt dennoch Euren Teil der Abmachung eingehalten. Ich werde sehen, wie ich Euch helfen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[8950] = { id = 8950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verzauberung des Aufhetzers", description = "Es wäre mir ein Leichtes, das Banner mit der von Euch benötigten Verzauberung zu belegen, {name}. Bedauerlicherweise verfüge ich allerdings nicht über die benötigten Materialien, da diese Art der Verzauberung nicht hoch im Kurs steht.\n\nIch werde die Essenz von einem der Eldrethgeisterwesen, die diese Hallen durchstreifen, einige Dunkelrunen aus Scholomance und ein paar große glänzende Splitter benötigen. Bringt mir diese Materialien und ich werde die Verzauberung für Euch vornehmen.", sourceObjective = "Bringt Falrin Rankenweber in Düsterbruch 1 Essenz eines spöttischen Geisterwesens, 4 Dunkelrunen und 8 große glänzende Splitter.", progress = "Habt Ihr die von mir benötigten Materialien zusammengesammelt, {name}?", completion = "Ja, damit sollte es funktionieren. Wenn ich fertig bin, wird keine Kraft in Azeroth Euer Opfer davon abhalten können, Eure Herausforderung anzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8951] = { id = 8951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Kehrt mit einem Paar Stiefel des Wildherzens, einem Kilt des Wildherzens und einer Schiftung des Wildherzens zu Deliana in Eisenschmiede zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8952] = { id = 8952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Kehrt mit einem Paar Bestienjägerstiefeln, einer Bestienjägerhose und einem Bestienjägermantel zu Deliana in Eisenschmiede zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8953] = { id = 8953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Kehrt mit einem Paar Stiefel des Magisters, Gamaschen des Magisters und einem Mantel des Magisters zu Deliana in Eisenschmiede zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8954] = { id = 8954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Kehrt mit einem Paar Stiefel des Lichts, Beinplatten des Lichts, und einer Schiftung des Lichts zu Deliana in Eisenschmiede zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8955] = { id = 8955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Kehrt mit einem Paar Sandalen des Gläubigen, einem Rock des Gläubigen und einem Mantel des Gläubigen zu Deliana in Eisenschmiede zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8956] = { id = 8956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Kehrt mit einem Paar Stiefel der Schattenkunst, einer Hose der Schattenkunst und einer Schiftung der Schattenkunst zu Deliana in Eisenschmiede zurück.", progress = "Ihr seid zurück, {name}. Ihr müsst mir unbedingt berichten, was Ihr herausgefunden habt. Aber zuerst zu Eurer Belohnung.", completion = "Ich kann einfach nicht glauben, dass all unsere Leben nur wegen dieses dummen Amuletts verwirkt sind. Seid Ihr sicher, dass Anthion Bodley erwähnte?\n\nNun, Ihr habt ganze Arbeit geleistet, also jetzt zu Eurer Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[8957] = { id = 8957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.", sourceObjective = "Kehrt mit einem Paar Stiefel der Elemente, einem Kilt der Elemente und Schulterstücken der Elemente zu Mokvar in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8958] = { id = 8958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Kehrt mit einem Paar Sandalen der Furcht, Gamaschen der Furcht und einem Mantel der Furcht zu Deliana in Eisenschmiede zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8959] = { id = 8959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Kehrt mit einem Paar Stiefel der Ehre, Beinplatten der Ehre und einer Schiftung der Ehre zu Deliana in Eisenschmiede zurück.", progress = "Ihr seid zurück, {name}. Ihr müsst mir unbedingt berichten, was Ihr herausgefunden habt. Aber zuerst zu Eurer Belohnung.", completion = "Ich kann einfach nicht glauben, dass all unsere Leben nur wegen dieses dummen Amuletts verwirkt sind. Seid Ihr sicher, dass Anthion Bodley erwähnte?\n\nNun, Ihr habt ganze Arbeit geleistet, also jetzt zu Eurer Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[8960] = { id = 8960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bodleys trauriges Schicksal", description = "Wir müssen also die restlichen Stücke des Amuletts wiederbeschaffen? Bodley zu finden, könnte sich als schwierig erweisen. Er begab sich zurück in den Schwarzfels, um die Schwarzfelsspitze zu betreten, und kam nie zurück.\n\nIch würde Euch raten, den Geisterdetektor des Goblins mitzunehmen, denn ich befürchte, ihm könnte etwas Schlimmes zugestoßen sein.", sourceObjective = "Reist zum Schwarzfels und benutzt den extradimensionalen Geisterdetektor, um Bodley nahe der Schwarzfelsspitze zu finden.", completion = "Ich bin ja so froh, dass Ihr mich sehen könnt. Endlich habe ich jemanden, mit dem ich reden kann!\n\nWerdet Ihr uns helfen, {name}? Uns dabei helfen, das wiedergutzumachen, was wir verbrochen haben? Sollte es stimmen, dass Ihr bereits das obere Stück von Lord Valthalaks Amulett besitzt, dann kann ich Euch dabei behilflich sein, die anderen Stücke zu finden, sie wieder zusammenzufügen und dieser Angelegenheit ein Ende zu bereiten.\n\nAch ja, mein Name ist Bodley. Schön, Euch kennen zu lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8961] = { id = 8961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die drei Könige der Flammen", description = "Um Lord Valthalak zu beschwören, müssen wir zunächst die anderen beiden Drittel des Amuletts beschaffen. Und dafür brauchen wir wiederum ein Räuchergefäß und einige ganz spezielle Kohlen, die darin verbrannt werden müssen.\n\nEs gibt drei hochrangige Feuerelementare, von denen wir diese Kohlen bekommen können: Lord Incendius in den Schwarzfelstiefen, Feuerwache Glutseher in der Schwarzfelsspitze und der Fürst der Asche in Silithus. Sammelt die Kohlen aus ihren Überresten auf und kehrt dann mitsamt eines geheiligten Räuchergefäßes zu mir zurück. Ihr könnt das Räuchergefäß von der Argentumdämmerung kaufen, wenn sie Euch wohlwollend gesinnt ist.", sourceObjective = "Bringt Bodley im Schwarzfels Incendius' Pyrophor, Glutsehers Glut, die Asche des Fürsten und ein geheiligtes Räuchergefäß.", progress = "Wir waren Narren, diesen letzten Auftrag anzunehmen. Er sollte unser aller Untergang sein. Wenn wir bloß nicht versehentlich Lord Valthalaks Seele gestohlen hätten, die in dem Amulett verwahrt war. Wären einige von uns nicht so gierig gewesen, das Amulett unter sich aufzuteilen, wäre ich jetzt noch am Leben und könnte irgendwo sitzen und ein kühles Bier trinken oder vielleicht sogar mit einem meiner Kinder spielen.\n\n{name}, lasst die Habsucht der Unehrenhaften nicht auch Euch ins Verderben reißen.", completion = "Ich bin beeindruckt, {class}, aber wir haben keine Zeit zu verlieren. Ich werde Euch nun Euren nächsten Auftrag geben, da ich noch einige weitere Komponenten benötige, bevor wir fortfahren können.\n\nSprecht erneut mit mir, wenn Ihr bereit sein, Euch den nächsten vor Euch liegenden Herausforderungen zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8962] = { id = 8962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, {class}. Jetzt, da wir das Räuchergefäß haben und es anzünden können, brauchen wir noch ein paar weitere Dinge, die wir hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nMor Grauhuf, unser bester Druide, hatte viele enge Freunde im Zirkel des Cenarius, von denen einige den Silithiden zum Opfer gefallen sind. Ihr müsst mir einige Druidenüberreste von den Silithiden beschaffen, die den Bau des Regalschwarms im Südosten von Silithus bewohnen.", sourceObjective = "Bringt Bodley im Schwarzfels einige Druidenüberreste.", progress = "Seid Ihr schon mit dem zurückgekehrt, worum ich Euch gebeten habe, {class}?", completion = "Ihr habt gute Arbeit geleistet, {name}. Ich werde die Essenz der Überreste in das Räuchergefäß geben.\n\nJetzt müsst Ihr Euch nur noch in Kriegsmeister Voones Kammer in Tazz'Alaor in der unteren Blackrockspitze begeben und mittels des Räuchergefäßes den korrupierten Geist meines ehemaligen Kameraden, Mor Grayhoof, beschwören. Er wird nicht ruhen können, bis er von seinem Stück des Amuletts befreit wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[8963] = { id = 8963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, {class}. Jetzt, da wir das Räuchergefäß haben und es anzünden können, brauchen wir noch ein paar weitere Dinge, die wir hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nIsalien, unsere Priesterin, wuchs in Sternenhauch in Winterquell auf. Ihr müsst mir ein Relikt von Sternenhauch von den Frosthagelriesen der Frosthauchschlucht im Süden von Winterquell bringen, die dafür bekannt sind, von Zeit zu Zeit den Norden unsicher zu machen.", sourceObjective = "Bringt Bodley im Schwarzfels ein Relikt von Sternenhauch.", sourceObjectiveStatus = "unverified-source-field" }
quests[8964] = { id = 8964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, {class}. Jetzt, da wir das Räuchergefäß haben und es anzünden können, brauchen wir noch ein paar weitere Dinge, die wir hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist um die Geister meiner verstorbenen Kameraden herbeizurufen.\n\nDie Geschwister, Jarien und Sothos, glaubten fest an die Lehren des Scharlachroten Kreuzzugs. Sie strebten danach, Ritter dieser abscheulichen Organisation zu werden. Geht zu Tyrs Hand, in den östlichen Pestländern, und beschafft mir ein gleißendes Schwert des Zeloten von den dortigen Prätorianern.", sourceObjective = "Bringt Bodley im Schwarzfels ein gleißendes Schwert des Zeloten.", progress = "Seid Ihr schon mit dem zurückgekehrt, worum ich Euch gebeten habe, {class}?", completion = "Gute Arbeit, {name}. Ich werde die Essenz des Schwertes in das Räuchergefäß geben.\n\nJetzt müsst Ihr Euch nur noch zum Purpurthron in der scharlachroten Bastion in Stratholme begeben und das Räuchergefäß benutzen, um die Geister meiner ehemaligen Verbündeten, Jarien und Sothos, zu beschwören. Ihre Seelen wurden durch den Einfluss des in Lord Valthalaks Amulett enthaltenen Seelenfragments sicherlich noch weiterhin korrupiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[8965] = { id = 8965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, {class}. Jetzt, da wir das Räuchergefäß haben und es anzünden können, brauchen wir noch ein paar weitere Dinge, die wir hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nKormok, ein Ogernekromant, der unsererm Bund angehörte, liebte es die Seelen der verbannten Toten von der Fegefeuerinsel, nahe der Südküste der Vorgebirge des Hügellands, herbeizurufen. Geht dorthin und beschafft mir etwas Seelenasche der Verbannten von ihren Überresten.", sourceObjective = "Bringt Bodley im Schwarzfels etwas Seelenasche der Verbannten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8966] = { id = 8966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das linke Stück von Lord Valthalaks Amulett", description = "Ein Freund von mir, Mor Grauhuf, war der Erste, der Lord Valthalaks Amulett und dem darin enthaltenen, korrupierenden Seelenfragment zum Opfer fiel. Nachdem wir Valthalaks Zauberbuch und Amulett gestohlen hatten, flohen wir um unser Leben aus dem oberen Teil der Schwarzfelsspitze. Während unserer überstürzten Flucht, fiel Mor in den unteren Teil der Schwarzfelsspitze hinab.\n\nWir erfuhren später, dass er den Fall überlebt hatte und von Kriegsmeister Voone gefangengenommen und gefoltert worden war. Später schlichen sich Spektrale Assassine in die Schwarzfelsspitze ein und erschlugen Mor vor Voones Augen.", sourceObjective = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Mor Grauhuf zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", progress = "Es ist vollbracht? Ihr habt das linke Stück von Lord Valthalaks Amulett und dem Geist von meinem alten Kameraden, Mor Grayhoof, zu seiner ewigen Ruhe verholfen?", completion = "Ihr habt eine gute Tat vollbracht, {name}. Ein Geist ruht nun in Frieden, aber es gibt noch viel zu tun, bevor wir dies durchgestanden haben.\n\nBedauerlicherweise ist mir nicht bekannt, wo derjenige starb, der das rechte Stück des Amuletts in seinem Besitz hatte. Aber keine Sorge, zu meinen Lebzeiten verstand ich mich ein wenig auf die Kunst der Wahrsagerei. Ich habe eine weitere Aufgabe für Euch, die es uns erlauben sollte, das letzte Stück aufzuspüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[8967] = { id = 8967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das linke Stück von Lord Valthalaks Amulett", description = "Wir erfuhren später, während wir alle unser Bestes taten, um zu überleben, dass Isalien, eine Nachtelfenpriesterin, die unserer Gruppe angehörte, in die Heimatstadt der Urahnen der Nachtelfen zurückgekehrt war - jetzt als Düsterbruch bekannt. Demzufolge, was uns berichtet wurde, zog es sie sowohl aus persönlichen Gründen dorthin zurück, als auch weil sie die Geheimnisse ihres Stücks des Amuletts ergründen wollte.\n\nAllerdings gelang es ihr nicht, dieses Wissen zu erlangen. Wie uns zugetragen wurde, wurde sie am Schrein von Eldretharr von Alzzin dem Wildformer und seinen Schergen in einen Hinterhalt gelockt.", sourceObjective = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Isalien zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8968] = { id = 8968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das linke Stück von Lord Valthalaks Amulett", description = "Die Geschwister, Jarien und Sothos, beschlossen, sich dem Scharlachroten Kreuzzug anzuschließen, nachdem sich unser Söldnerbund aufgelöst hatte. Das linke Stück von Valthalaks Amulett nahmen sie mit sich. Ich war froh, sie los zu sein, aber jetzt brauchen wir dieses Stück zurück.\n\nUnseren Informationen zufolge, wurden sie vom obersten Kreuzzügler Dathrohan höchstpersönlich hingerichtet, da sie die Initiationsriten in seiner Kammer in der scharlachroten Bastion nicht bestanden hatten. \n\nWie dem auch sei, wir... und damit meine ich Ihr, müssen dieses Stück des Amuletts zurückbekommen.", sourceObjective = "Benutzt das Räuchergefäß der Beschwörung, um die Geister von Jarien und Sothos zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8969] = { id = 8969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das linke Stück von Lord Valthalaks Amulett", description = "Jetzt, wo wir alles beisammen haben was wir benötigen, wird es Zeit uns darüber zu unterhalten, wen Ihr beschwören werdet.\n\nKormok war ganz okay, für einen Oger, bis er sich der Nekromantie zuwandte. Von da ab wurde es für jeden im Bund ganz schön gruselig. Es überraschte also niemanden, dass er mit seinem Stück des Amuletts in sein neues Zuhause verschwand, Scholomance.\n\nAber selbst dort, oder vielleicht gerade dort, war er nicht vor den spektralen Assassinen sicher. Sie erschlugen ihn vor den Augen seines Meisters, Ras Frostraunen.", sourceObjective = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Kormok zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", progress = "Ich gratuliere Euch, {name}, solltet Ihr mit dem linken Stück von Lord Valthalaks Amulett zurückgekehrt sein. Wenn Ihr es allerdings noch nicht habt, solltet Ihr Euch beeilen. Wir haben keine Zeit zu verlieren!", completion = "Gute Arbeit, {name}! Kormok war gar kein so schlechter Kerl, für einen Oger, jedenfalls nicht zu seinen Lebzeiten. Ich hoffe, sein Geist findet den Frieden, den er verdient. Aber es gibt noch mehr für uns zu tun.\n\nBedauerlicherweise ist mir nicht bekannt, wo derjenige starb, der das rechte Stück des Amuletts in seinem Besitz hatte. Aber keine Sorge, zu meinen Lebzeiten verstand ich mich ein wenig auf die Kunst der Wahrsagerei. Ich habe eine weitere Aufgabe für Euch, die es uns erlauben sollte, das letzte Stück aufzuspüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[8970] = { id = 8970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich sehe die Insel Alcaz in Eurer Zukunft", description = "Wie ich schon sagte, {class}, zu meinen Lebzeiten spielte ich mit dem Gedanken, ein Wahrsager zu werden. Aber damit kann man bei Weitem nicht so viel Profit machen, wie Ihr vielleicht denken würdet. Die Wahrsagerei kann nämlich ganz schön gefährlich sein und die Reagenzen sind selten und teuer. Aber ich weiß genug, um den Fundort des letzten Amulettstücks zu erahnen, und somit auch den Geist meines ehemaligen Kameraden.\n\nUnd deshalb benötige ich Eure Hilfe, {name}. Ihr müsst zur Insel Alcaz vor der Küste der Düstermarschen reisen und Bluttang von den Naga der Strashaz, die dort leben, zusammensammeln.", sourceObjective = "Bringt Bodley im Schwarzfels 20 Einheiten Bluttang von den Naga der Strashaz.", progress = "Bluttang, {name}, davon brauche ich einen großen Haufen, um meine Wahrsagermagie wirken zu können. Ihr werdet vermutlich ein paar Kameraden mit zur Insel Alcaz nehmen müssen, um den Bluttang einzusammeln. Diese Strashaz sind ziemlich fiese Gesellen!", completion = "Ehrlich gesagt bin ich überrascht, dass Ihr in einem Stück zurückgekehrt seid, {name}. Aber die Insel Alcaz ist momentan vermutlich Eure geringste Sorge.\n\nLasst mir jetzt ein wenig Zeit, man kann nicht einfach mit den Fingern schnippen und zuverlässige Resultate von der Wahrsagerei erwarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8971] = { id = 8971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
