quests[9074] = { id = 9074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurt des Erdspalters", description = "Würdet Ihr mir die Ehre erweisen und mir die Rüstungen derer bringen, die bei der Verteidigung dieses Landes gefallen sind?\n\nDie Rüstungen wurden entweiht und zweifellos für Böses missbraucht; allerdings können sie mit kampfzerschlissenen Rüstungsstücken erneuert werden und somit noch einmal im Kampf getragen werden.\n\nBringt mir die Überbleibsel der Gefallenen, sowie die läuternden Materialien, dann soll Erdspalter Euer sein.\n\nSucht in Naxxramas.", sourceObjective = "Rimblat Erdspalter bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch einen Gurt des Erdspalters anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Gurt, 8 kampfzerschlissene Kettenstücke, 1 Arkanitbarren und 3 Nexuskristalle.", sourceObjectiveStatus = "unverified-source-field" }
quests[9075] = { id = 9075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handgelenksschutz des Erdspalters", description = "Würdet Ihr mir die Ehre erweisen und mir die Rüstungen derer bringen, die bei der Verteidigung dieses Landes gefallen sind?\n\nDie Rüstungen wurden entweiht und zweifellos für Böses missbraucht; allerdings können sie mit kampfzerschlissenen Rüstungsstücken erneuert werden und somit noch einmal im Kampf getragen werden.\n\nBringt mir die Überbleibsel der Gefallenen, sowie die läuternden Materialien, dann soll Erdspalter Euer sein.\n\nSucht in Naxxramas.", sourceObjective = "Rimblat Erdspalter bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch einen Handgelenksschutz des Erdspalters anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Handgelenksschutz, 6 kampfzerschlissene Kettenstücke, 1 Arkanitbarren und 2 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[9076] = { id = 9076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getriebener Rädelsführer", description = "Die Getriebenen sind so auf den Verzehr von fauler Magie konzentriert, sie haben nicht einmal gemerkt, dass wir den Großteil unserer Waffen wieder an uns gebracht haben. Wir können uns allerdings nicht auf ihren Zustand der Benommenheit verlassen. Es ist an der Zeit für einen ausschlaggebenden Angriff. Lasst uns anhand ihres Anführers Aldaron ein Exempel statuieren. Er wurde im obersten Teil des Gebäudes beim Ankerplatz gesichtet. Bringt mir seinen Kopf, ich werde Euch entsprechend entlohnen.", sourceObjective = "Bringt Aldarons Kopf zu Velendris Weißflor nahe des Ankerplatzes der Sonnensegel im Immersangwald.", progress = "Nun, habt Ihr seinen Kopf? Verschwendet nicht meine Zeit, {name}.", completion = "Ihr habt ihn also doch noch bezwungen! Meine Männer hatten ihn natürlich schon geschwächt.\n\nDas war ein Scherz, {class}. Ihr habt Euch gut geschlagen. Wenn Ihr weiterhin eine weiße Weste behaltet, werdet Ihr Euch noch einen Namen machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9077] = { id = 9077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brustplatte der Knochensense", description = "Wenn Ihr etwas von der Knochensensenrüstung wollt, dann werdet Ihr die Materialien dafür auftreiben müssen.\n\nGeht nach Naxxramas, der schwebenden Metropole des Todes, hier oben im Himmel, und sucht nach entweihter Rüstung, sowie kampfzerschlissenen Rüstungsstücken. Bringt alles mitsamt der Materialien zum Zusammenfügen zurück und Ihr bekommt Eure Knochensensenrüstung. Oh, Ihr werdet mich natürlich auch für meine Mühen entschädigen müssen... Ich stelle die Knochen zur Verfügung.", sourceObjective = "Rohan der Assassine bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch eine Brustplatte der Knochensense anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Brustplatte, 25 kampfzerschlissene Lederstücke, 2 Arkanitbarren und 6 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
