quests[9084] = { id = 9084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armschienen der Knochensense", description = "Wenn Ihr etwas von der Knochensensenrüstung wollt, dann werdet Ihr die Materialien dafür auftreiben müssen.\n\nGeht nach Naxxramas, der schwebenden Metropole des Todes, hier oben im Himmel, und sucht nach entweihter Rüstung, sowie kampfzerschlissenen Rüstungsstücken. Bringt alles mitsamt der Materialien zum Zusammenfügen zurück und Ihr bekommt Eure Knochensensenrüstung. Oh, Ihr werdet mich natürlich auch für meine Mühen entschädigen müssen... Ich stelle die Knochen zur Verfügung.", sourceObjective = "Rohan der Assassine bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Armschienen der Knochensense anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Armschienen, 6 kampfzerschlissene Lederstücke, 1 Arkanitbarren, 2 geschmeidige unverwüstliche Bälge und 10 Goldstücke.", progress = "Wie soll ich, ohne die von mir benötigten Gegenstände, Eurer Meinung nach irgendetwas zu Stande bekommen?", completion = "Die Armschienen sind fertig, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9085] = { id = 9085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten der Verdammnis", description = "Nachdem Ihr die Verteidigung der Beschwörungskreise der Geißel in den angegriffenen Gebieten ausgeschaltet habt, könnt Ihr den Akolythen, die sie beschützen, gegenübertreten.\n\nIn Wirklichkeit handelt es sich dabei nicht um richtige Wesen, sondern um Schatten, die zu den beängstigendsten Kreaturen des Lichkönigs zählen. Sie können mit Hilfe der nekrotischen Runen, die sie bei sich tragen, Gestalt annehmen und dann mit Magie oder dem Einsatz von Waffen zerstört werden.", sourceObjective = "Geht zu einem Beschwörungskreis und tötet einen Schatten der Verdammnis. Kehrt dann zu Kommandant Thomas Helleran bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern zurück.", completion = "Ausgezeichnete Arbeit, {name}. Sind die Schatten erstmal zerstört, ist es nur noch eine Frage der Zeit, bis der Lichkönig seine Nekropolen entgültig zurückruft und uns in Frieden lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9086] = { id = 9086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tunika des Traumwandlers", description = "Im letzten Krieg sind zahllose Helden umgekommen und auch heute fallen der Geißel täglich noch viele weitere Streiter zum Opfer. Den Körpern der Gefallenen werden die Rüstungen entwendet und zurück nach Naxxramas gebracht, um dort für unbekannte Zwecke missbraucht zu werden.\n\nMacht die entweihten Rüstungsteile und kampfzerschlissene Rüstungsstücke ausfindig. Besorgt mir zusätzlich die anderen Bestandteile, die ich benötige, dann werde ich eine Rüstung des Traumwandlers für Euch anfertigen.", sourceObjective = "Rayne bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch eine Tunika des Traumwandlers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Tunika, 25 kampfzerschlissene Lederstücke, 6 geschmeidige unverwüstliche Bälge und 2 Nexuskristalle.", sourceObjectiveStatus = "unverified-source-field" }
quests[9087] = { id = 9087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beinschützer des Traumwandlers", description = "Im letzten Krieg sind zahllose Helden umgekommen und auch heute fallen der Geißel täglich noch viele weitere Streiter zum Opfer. Den Körpern der Gefallenen werden die Rüstungen entwendet und zurück nach Naxxramas gebracht, um dort für unbekannte Zwecke missbraucht zu werden.\n\nMacht die entweihten Rüstungsteile und kampfzerschlissene Rüstungsstücke ausfindig. Besorgt mir zusätzlich die anderen Bestandteile, die ich benötige, dann werde ich eine Rüstung des Traumwandlers für Euch anfertigen.", sourceObjective = "Rayne bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Beinschützer des Traumwandlers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Beinschützer, 20 kampfzerschlissene Lederstücke, 8 geschmeidige unverwüstliche Bälge und 1 Nexuskristall.", sourceObjectiveStatus = "unverified-source-field" }
