quests[9094] = { id = 9094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handschuhe der Argentumdämmerung", progress = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", completion = "Ihr habt gute Arbeit geleistet, {name}. Nehmt den von Euch gewählten Handschutz als Dank für Eure Mühen." }
quests[9095] = { id = 9095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostfeuerrobe", description = "Als Behüterin hatte ich Zugang zu Vielem von Medivhs persönlicher Habe. Die Folianten waren für micht die aufschlussreichsten Gegenstände. Während die Mehrheit der Bücher aus - sagen wir es ganz offen - Schund bestand, gab es auch einige Schmuckstücke darunter. Einer dieser Folianten beschrieb die Herstellung eines Rüstungssets, passend für einen Erzmagier: Frostfeuer.\n\n<Angela deutet auf ihren Kopf.>\n\nEs ist alles hier drin und ich bin bereit, die Früchte dieses Wissens mit Euch zu teilen, solange Ihr mir die nötigen Materialien besorgt.", sourceObjective = "Erzmagierin Angela Dosantos bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch eine Frostfeuerrobe anfertigen, wenn Ihr ihr folgende Gegenstände bringt: 1 entweihte Robe, 25 kampfzerschlissene Stoffstücke, 4 Einheiten Mondstoff und 2 Nexuskristalle.", progress = "Mit den erforderlichen Materialien und Reagenzien bin ich in der Lage, die mythische Frostfeuerrüstung wieder herzustellen.", completion = "Vergesst nicht, dass unkontrollierte Macht genauso zerstörerisch wie ungenutzte Macht ist, {class}. Lasst Vorsicht walten, wenn Ihr Frostfeuer tragt.", sourceObjectiveStatus = "unverified-source-field" }
