quests[9183] = { id = 9183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Strahlender Reif", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer BS-80:\n\n3 strahlende Reifen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 3 strahlende Reifen und die Handwerksverfügung für die strahlenden Reifen zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Ich kann es nicht fassen, dass Metz ernsthaft erwartet, dass unsere Truppen diesen minderwertigen Mist tragen, um sich gegen die eisigen Angriffe der Geißel zu verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9184] = { id = 9184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Tückisches Lederstirnband", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer LW-971:\n\n10 tückische Lederstirnbänder.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 10 tückische Lederstirnbänder und die Handwerksverfügung für die tückischen Lederstirnbänder zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Ganz schön tückisch, diese Dinger...", sourceObjectiveStatus = "unverified-source-field" }
quests[9185] = { id = 9185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Unverwüstliches Rüstungsset", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer LW-448:\n\n25 unverwüstliche Rüstungssets.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 25 unverwüstliche Rüstungssets und die Handwerksverfügung für die unverwüstlichen Rüstungssets zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Unverwüstliche Rüstungssets sind vielseitig einsetzbar, {name}. Sie taugen nicht nur als zusätzliche Rüstungsschicht, sondern geben auch hervorragende Teekannenwärmer ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[9186] = { id = 9186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Tückischer Ledergürtel", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer LW-736:\n\n9 tückische Ledergürtel.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 9 tückische Ledergürtel und die Handwerksverfügung für die tückischen Ledergürtel zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9187] = { id = 9187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Runenverzierte Lederhose", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer LW-8485:\n\n4 runenverzierte Lederhosen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 4 runenverzierte Lederhosen und die Handwerksverfügung für die runenverzierten Lederhosen zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Die Druiden werden den Aufwand zu Schätzen wissen, welcher zur Herstellung dieser Hosen notwendig war. Vielen Dank, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9188] = { id = 9188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Hellstoffhose", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer TR-95:\n\n6 Hellstoffhosen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 6 Hellstoffhosen und die Handwerksverfügung für die Hellstoffhosen zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Bei allen guten Geistern, diese Dinger blenden mich ja fast schon! Verrückt, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[9189] = { id = 9189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung an das Grabmal", description = "Ihr habt das Herz der Fürstin gerührt, obwohl es nicht mehr schlägt.\n\nIch habe Anweisungen, die zum Grabmal nach Silberwald gebracht werden müssen. Berater Sorrelon repräsentiert uns und berät dort die Verlassenen.\n\nDie kürzeste Route, wenn man von ihren fliegenden Fledermäusen absieht, ist es, Unterstadt zu verlassen und die Straße nach Süden zu nehmen. Es gibt Wegweiser, also sollte es nicht zu schwer sein, den Ort zu finden. Aber nehmt Euch in Acht, das Grabmal selbst ist eine zerfallene Gruft.\n\nDiese Verlassenen sind schon merkwürdige Kreaturen.", sourceObjective = "Bringt die versiegelten Befehle der Sin'dorei zu Berater Sorrelon beim Grabmal in Silberwald.", progress = "Seid gegrüßt, Bruder. Welche Neuigkeiten bringt Ihr?", completion = "Wie ich sehe, setzt Botschafter Sonnenleid große Hoffnungen auf Euren Aufstieg in den Rängen der Sin'dorei. Die Angelegenheit mit Lady Sylvanas war allerdings unangenehm. Macht Euch nichts daraus, {name}, es war richtig von Euch, die Halskette zurückzubringen. Sie hätte Euch dankbar sein sollen, aber so ist das nun mal mit dem Adel.\n\nSolange Ihr hier seid und falls Ihr Euch entschließt, Aufträge für die Verlassenen zu übernehmen, zeigt bitte Euer bestes Benehmen. Ihr wollt doch unser neues Bündnis mit der Horde nicht gefährden, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[9190] = { id = 9190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Runenstoffstiefel", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer TR-635:\n\n8 Runenstoffstiefel.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 8 Runenstoffstiefel und die Handwerksverfügung für die Runenstoffstiefel zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Bei Bronzebeards Bart! Ihr habt mir tatsächlich Runenstoffstiefel gebracht... Schätze, ich habe diese Wette verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[9191] = { id = 9191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Runenstofftasche", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer TR-9999:\n\n8 Runenstofftaschen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 8 Runenstofftaschen und die Handwerksverfügung für die Runenstofftaschen zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Heiliger Schnürsenkel! Ist es das, was ich denke? Unsere Soldaten beschweren sich immer wieder über den Mangel an Taschen, um ihre ganze Ausrüstung zu verstauen. Einer hat sogar seine Feldrationen in seinen Backen verstaut... verdammter Nager.\n\nDas wird die Gemüter bestimmt abkühlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9192] = { id = 9192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in den Grubenlichtminen", description = "Die Grubenlichtminen im Südwesten wurden von einem Gnollklan, der sich die Schwarzpfoten nennt, überrannt. Ich muss Euch sicherlich nicht daran erinnern, wie wichtig diese Minen in strategischer Hinsicht für unseren fortwährenden Schlachtzug in den Geisterlanden sind!\n\nNehmt die Straße, die nach Süden führt, und haltet Euch rechts an der Wegzweigung. Kurz nach dem Ziggurat zur Rechten kommt ein kurzer Trampelpfad Richtung Westen. Folgt ihm.\n\nWir brauchen das Erz!", sourceObjective = "Tötet 8 Gnolle der Schwarzpfoten, 6 Strauchdiebe der Schwarzpfoten und 4 Schamanen der Schwarzpfoten. Kehrt anschließend zu Todespirscher Maltendis in Tristessa in den Geisterlanden zurück.", completion = "Da habt Ihr mal ordentlich Blut fließen lassen, {class}. Die Minenarbeiter können jetzt wieder an die Arbeit. Sie sind sicher enttäuscht, dass ihre Pause jetzt vorbei ist, aber wir brauchen nun mal mehr Erz, um Rüstungen und Waffen herzustellen.\n\nHier, nehmt dies als Lohn für Eure pflichtbewusste Tat. Lasst Rüstung und Waffen reparieren und trinkt einen auf mich.", sourceObjectiveStatus = "unverified-source-field" }
quests[9193] = { id = 9193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersucht die Amanikatakomben", description = "{class}, wir haben aus zuverlässigen Quellen erfahren, dass die Trolle, die in den Amanikatakomben innerhalb des Sonnenhügels begraben wurden, wieder von den Toten auferstanden sind. Dame Auriferous möchte, dass Ihr die Katakomben untersucht und dass Ihr alle leblosen Überreste, die Ihr dort auffindet, verbrennt. Die Auferstehung weiterer Kreaturen soll dadurch verhindert werden.\n\nIhr kommt am schnellsten dorthin, wenn Ihr Richtung Norden reist und dann die erste Abzweigung nach rechts nehmt. Somit gelangt Ihr auf die Nordseite des Hügels, seht Richtung Süden nach dem Eingang.", sourceObjective = "Untersucht die Amanikatakomben und verbrennt 10 mumifizierte Trollüberreste. Kehrt anschließend zu Beraterin Valwyn in Tristessa in den Geisterlanden zurück.", progress = "Das ist eine äußerst makabere und würdelose Angelegenheit, {class}. Ich kann Euch doch vertrauen, dass Ihr diesen Auftrag zur vollsten Zufriedenheit der Milady erfüllt?", completion = "Abscheulich, aber glaubt mir, es war notwendig. Ihr habt uns einen großen Dienst mit Euren Nachforschungen erwiesen, {class}. Bitte, nehmt dies als Zeichen unserer Großzügigkeit und Anerkennung an.", sourceObjectiveStatus = "unverified-source-field" }
quests[9194] = { id = 9194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Runenstoffrobe", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer TR-7229:\n\n8 Runenstoffroben.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 8 Runenstoffroben und die Handwerksverfügung für die Runenstoffroben zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Das war doch völlig unnötig! Nein wirklich, wer hat sich das denn einfallen lassen? Keiner von uns wird ernsthaft beim Sturm auf Naxxramas eine Robe tragen wollen. Was hat Metz sich bloß dabei gedacht?\n\n<Rottenkommandant Stonebruiser seufzt.>\n\nBah, nur wieder eine weitere Ladung unnützes Zeug, das ich an die Front schaffen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[9195] = { id = 9195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Goblinpioniersprengladung", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer EN-11:\n\n20 Goblinpioniersprengladungen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 20 Goblinpioniersprengladungen und die Handwerksverfügung für die Goblinpioniersprengladungen zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9196] = { id = 9196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Thoriumgranate", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer EN-7:\n\n20 Thoriumgranaten.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 20 Thoriumgranaten und die Handwerksverfügung für die Thoriumgranaten zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Die Herstellung dieser Dinger muss ganz schön kostspielig gewesen sein. Hab ich Recht, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[9197] = { id = 9197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Gnomenkampfhuhn", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer EN-0:\n\n4 Gnomenkampfhühner.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 4 Gnomenkampfhühner und die Handwerksverfügung für die Gnomenkampfhühner zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
